def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    sixes = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    segments = []
    for i, (r0, c0) in enumerate(ones):
        for r1, c1 in ones[i + 1:]:
            if r1 != r0 and abs(r1-r0) == abs(c1-c0):
                segments.append((r0, c0, r1, c1))
    for r0, c0, r1, c1 in segments:
        dr = 1 if r1 > r0 else -1
        dc = 1 if c1 > c0 else -1
        r, c = r0, c0
        while True:
            if out[r][c] != 6:
                out[r][c] = 1
            if (r, c) == (r1, c1):
                break
            r += dr
            c += dc
    # A 6 on a 1-segment spawns the crossing diagonal in 6, extending to edges.
    for r0, c0 in sixes:
        for a, b, x, y in segments:
            if abs(x-a) != abs(y-b):
                continue
            on_segment = (min(a, x) <= r0 <= max(a, x) and
                          min(b, y) <= c0 <= max(b, y) and
                          abs(r0-a) == abs(c0-b))
            if on_segment:
                # This marker remains fixed; the 6 stroke is produced only by
                # the separate 6-marker diagonal, not by this intersecting marker.
                break
    return out
